YXRlICptcmIsIG1yYl92YWx1ZSBzZWxmKQogICBtcmJfaW50IGJhc2UgPSAxMDsKIAogICBtcmJf
Z2V0X2FyZ3MobXJiLCAifGkiLCAmYmFzZSk7Ci0jaWZkZWYgTVJCX1VTRV9CSUdJTlQKLSAgaWYg
KG1yYl9iaWdpbnRfcChzZWxmKSkgewotICAgIHJldHVybiBtcmJfYmludF90b19zKG1yYiwgc2Vs
